'use strict';
const http = require('http');

function request(method, path, body) {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: '127.0.0.1', port: 18080, method, path }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    });
    req.on('error', reject);
    if (body !== undefined) req.write(body);
    req.end();
  });
}

async function main() {
  const contentA = Buffer.alloc(200000, 'A');
  const contentB = Buffer.alloc(200000, 'B');

  const [resA, resB] = await Promise.all([
    request('PUT', '/blobs/race.txt', contentA),
    request('PUT', '/blobs/race.txt', contentB),
  ]);
  console.log('PUT A status', resA.status, 'PUT B status', resB.status);

  const got = await request('GET', '/blobs/race.txt');
  const isA = got.body.equals(contentA);
  const isB = got.body.equals(contentB);
  console.log('GET after race: status', got.status, 'length', got.body.length, 'matchesA', isA, 'matchesB', isB, 'pure', isA || isB);

  const [resC, resD] = await Promise.all([
    request('PUT', '/blobs/diff-1.txt', Buffer.from('one')),
    request('PUT', '/blobs/diff-2.txt', Buffer.from('two')),
  ]);
  console.log('different keys:', resC.status, resD.status);

  const list = await request('GET', '/blobs');
  const parsed = JSON.parse(list.body.toString());
  console.log('list keys:', parsed.map((b) => b.key).sort());
  const hasTmp = parsed.some((b) => b.key.includes('.tmp'));
  console.log('any tmp leaked into listing:', hasTmp);

  const health = await request('GET', '/healthz');
  console.log('healthz after all this:', health.status);
}

main().catch((err) => { console.error('FAILED', err); process.exit(1); });

